/**
 * Per-playbook runtime options, derived from the FSM input fields that no
 * `PlaybookSession` member or other linker-owned source supplies. The machine
 * seeds its transformation request from these; a Boss turn may still name or
 * replace either path through the classified entry or interrupt event.
 *
 * The FSM declares no `script` state, so no `cwd` option is emitted.
 */
export interface PlaybookRuntimeOptions {
  /** Path of the `text` source (`.md`) the transformation reads. */
  readonly sourcePath?: string;
  /** Path of the `gears` target (`.md`) the transformation writes. */
  readonly targetPath?: string;
}

/**
 * This artifact's exact live schema-3 host capability set: exactly
 * `authority`, `repository`, and `effectLedger`. The shared contract publishes
 * the repository and effect-ledger types; the authority object is the live
 * current-host binding of this artifact's id and schema, its detached role and
 * cohort declarations, the current configured working directory, the logical
 * session and lease-owner identities, and the canonical worktree, whose member
 * shape the shared contract does not publish.
 */
export interface HostCapabilities {
  readonly authority: object;
  readonly repository: XStateRepositoryCapability;
  readonly effectLedger: PlaybookEffectLedgerCapability;
}

const LABEL = 'text2gears';

const OPTION_KEYS = ['sourcePath', 'targetPath'] as const;

const isPlainObject = (value: unknown): value is Record<string, unknown> => {
  if (typeof value !== 'object' || value === null || Array.isArray(value))
    return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
};

const readOptionalPath = (
  source: Record<string, unknown>,
  key: (typeof OPTION_KEYS)[number],
): string | undefined => {
  const raw = source[key];
  if (raw === undefined) return undefined;
  if (typeof raw !== 'string' || raw.trim() === '') {
    throw new TypeError(`${LABEL} options: ${key} must be a non-empty string`);
  }
  return raw;
};

/**
 * Validate and JSON-snapshot the caller's configured options, rejecting
 * undeclared keys and non-conforming values, so the factory binds an immutable
 * options record before it constructs any actor.
 */
const snapshotOptions = (value: unknown): PlaybookRuntimeOptions => {
  if (value === undefined || value === null) return Object.freeze({});
  if (!isPlainObject(value)) {
    throw new TypeError(`${LABEL} options must be a plain object`);
  }
  for (const key of Reflect.ownKeys(value)) {
    if (
      typeof key !== 'string' ||
      !(OPTION_KEYS as readonly string[]).includes(key)
    ) {
      throw new TypeError(`${LABEL} options: undeclared option ${String(key)}`);
    }
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (
      descriptor === undefined ||
      !('value' in descriptor) ||
      !descriptor.enumerable
    ) {
      throw new TypeError(
        `${LABEL} options: ${key} must be an enumerable data property`,
      );
    }
  }
  const sourcePath = readOptionalPath(value, 'sourcePath');
  const targetPath = readOptionalPath(value, 'targetPath');
  return Object.freeze({
    ...(sourcePath !== undefined ? { sourcePath } : {}),
    ...(targetPath !== undefined ? { targetPath } : {}),
  });
};

/**
 * Boss-union arms whose exact judge fields and closed string values disappear
 * under TypeScript erasure. `BOSS_REPLY` and `NO_ACTION` are runtime-owned and
 * carry no entry here. Both path fields are optional in the FSM's event union,
 * so they stay optional in the classifier contract.
 */
const BOSS_EVENTS: readonly XStateBossEventSpec[] = [
  {
    type: 'TRANSFORMATION_REQUEST',
    fields: {
      sourcePath: { source: 'judge' },
      targetPath: { source: 'judge' },
    },
  },
  {
    type: 'BOSS_INTERRUPT',
    fields: {
      targetId: {
        source: 'judge',
        required: true,
        values: ['transformSource'],
      },
      sourcePath: { source: 'judge' },
      targetPath: { source: 'judge' },
    },
  },
];

/** String payload fields the FSM's Boss union declares. */
const TRANSITION_EVENT_FIELDS: readonly string[] = [
  'sourcePath',
  'targetPath',
  'targetId',
  'questionId',
  'answer',
];

/** The FSM declares no state that invokes the typed `player` actor. */
const ROLE_STATES: Readonly<Record<string, XStateRoleStateStatus>> = {};

/** No delegated-player state exists, so the governed map is explicitly empty. */
const OUTCOME_AUTHORITY: XStateOutcomeAuthoritySpec = {
  governedPlayerStates: {},
};

/**
 * Derived from the annotated `<field>: <verbatim final text>` result fields of
 * the FSM's delegated-player result maps. The FSM declares none, so the set is
 * empty; the direct-Captain `question` presentation field is injected by the
 * runtime from the visible call and is not a verbatim player field.
 */
const VERBATIM_PAYLOAD_FIELDS: ReadonlySet<string> = new Set<string>();

/**
 * Root `type: 'final'` states whose terminal outcome leaves the procedure
 * unfinished. Both `transformed` and `unrepresentable` are authored terminal
 * outcomes of item T2G-1, and no link option declares either as unfinished, so
 * the set is explicitly empty.
 */
const UNFINISHED_FINAL_STATE_IDS: ReadonlySet<string> = new Set<string>();

const spec: XStatePlaybookRuntimeSpecV3<PlaybookRuntimeOptions> = {
  label: LABEL,
  compat: { artifactSchema: 3, runtimeAbi: 1 },
  snapshotOptions,
  bossEvents: BOSS_EVENTS,
  transitionEventFields: TRANSITION_EVENT_FIELDS,
  roleStates: ROLE_STATES,
  outcomeAuthority: OUTCOME_AUTHORITY,
  verbatimPayloadFields: VERBATIM_PAYLOAD_FIELDS,
  unfinishedFinalStateIds: UNFINISHED_FINAL_STATE_IDS,
};

const createPlaybookRuntime: XStatePlaybookRuntimeFactory<
  XStatePlaybookRuntimeConstruction<PlaybookRuntimeOptions, HostCapabilities>,
  3
> = createXStatePlaybookRuntime<PlaybookRuntimeOptions, HostCapabilities>(
  text2gearsMachine,
  spec,
);

export default createPlaybookRuntime;

